sys_variable_value.value:
(function execute(inputs, outputs) {

    var token_primary = inputs.token;
    var payload_primary = inputs.payload;

    try { 
        var tokenBearer = token_primary;
        var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'adicionarBPFiador');
        r.setStringParameterNoEscape('token', tokenBearer);

        r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
        r.setRequestHeader('Content-Type', 'application/json');

        var requestBody = JSON.stringify(payload_primary);
        r.setRequestBody(requestBody);

        gs.info('### Corpo da requisição: POST Aditivo Fiador ' + requestBody);

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        gs.info('### SAPintegraUtils.POST Aditivo Fiado response body: ' + responseBody);

        var responseJSON = JSON.parse(responseBody);
        var returnCode = responseJSON.ReturnCode;

        if ((httpStatus == 200 || httpStatus == 201 || httpStatus == 202) &&
            (returnCode == "200" || returnCode == "201" || returnCode == "202")) {

            var contractNumber = responseJSON.ContractNumber;
            var messageDescription = responseJSON.MessageDescription; 
            var companyCode = responseJSON.CompanyCode;

            if (responseJSON.ReturnMessages && responseJSON.ReturnMessages.length > 0) {
                for (var i = 0; i < responseJSON.ReturnMessages.length; i++) {
                    var field = responseJSON.ReturnMessages[i].Field;
                    var message = responseJSON.ReturnMessages[i].Message;
                    var parameter = responseJSON.ReturnMessages[i].Parameter;
                    var msgType = responseJSON.ReturnMessages[i].MsgType;

                    gs.info('### ReturnMessages[' + i + ']: Field=' + field + ', Message=' + message + ', Parameter=' + parameter + ', MsgType=' + msgType);
                }
            }

            outputs.answer_script = 'Criação realizada com sucesso'; 
            outputs.http = httpStatus;
            outputs.code = returnCode;
            outputs.description = messageDescription;  
            outputs.message = messageDescription;      
        }else {
            outputs.messagedescriptionerror = responseJSON.MessageDescription; 
        }

    } catch (ex) {
        var message = ex.message;
        gs.error('Erro ao executar o script: ' + message);
    }

})(inputs, outputs);

